from pathlib import Path
import json
def series_chart(name):
 d=json.loads((Path(__file__).resolve().parent/name).read_text(encoding='utf-8'));rows=d['rows'];n=len(rows)
 L,R,T,B=90,1110,22,272;W=R-L;H=B-T
 x=lambda i:L+W*i/(n-1)
 def line(key,lo,hi):
  return ' '.join(('M' if i==0 else 'L')+f"{x(i):.1f} {B-H*(r[key]-lo)/(hi-lo):.1f}" for i,r in enumerate(rows))
 years=''.join(f'<text class="ax" x="{x(i):.0f}" y="{B+34}" text-anchor="start">{r["month"][:4]}</text><line class="tick" x1="{x(i):.1f}" y1="{B}" x2="{x(i):.1f}" y2="{B+10}"/>' for i,r in enumerate(rows) if r['month'].endswith('-01'))
 grid=''.join(f'<line class="grid" x1="{L}" y1="{B-H*v/6:.1f}" x2="{R}" y2="{B-H*v/6:.1f}"/><text class="ax gold" x="{L-14}" y="{B-H*v/6+7:.1f}" text-anchor="end">{v}%</text>' for v in (0,2,4,6))
 right=''.join(f'<text class="ax teal" x="{R+14}" y="{B-H*(v-3400)/1500+7:.1f}">{v:,}</text>' for v in (3500,4000,4500))
 def mark(i,key,lo,hi,label,dx,dy,anchor):
  return f'<circle class="dot" cx="{x(i):.1f}" cy="{B-H*(rows[i][key]-lo)/(hi-lo):.1f}" r="7"/><text class="note" x="{x(i)+dx:.1f}" y="{B-H*(rows[i][key]-lo)/(hi-lo)+dy:.1f}" text-anchor="{anchor}">{label}</text>'
 marks=mark(14,'fedfunds',0,6,'2022年3月 利上げ開始',-16,-16,'end')+mark(21,'sp500_month_end',3400,4900,'2022年10月 株価の底',18,8,'start')+mark(30,'fedfunds',0,6,'2023年7月 最後の利上げ',0,-22,'middle')
 return f'<svg class="series" viewBox="0 0 1200 320" aria-label="{d["episode"]}">{grid}{years}{right}<path class="line teal" pathLength="1" d="{line("sp500_month_end",3400,4900)}"/><path class="line gold" pathLength="1" d="{line("fedfunds",0,6)}"/>{marks}</svg>'
b=Path(__file__).resolve().parent.parent
slides=[]
def add(ch,content,cls=''):
 slides.append(f'<section class="slide {cls}" data-ch="{ch}">{content}</section>')
def head(n,title,sub=''):
 return f'<div class="eyebrow">{n}</div><h2>{title}</h2>'+ (f'<p class="lead">{sub}</p>' if sub else '')
def cards(items):
 return '<div class="cards">'+''.join(f'<article><small>{a}</small><h3>{c}</h3><p>{d}</p></article>' for a,c,d in items)+'</div>'
def question(ch,q,a,art=''):
 bg=f'<div class="answer-art" style="background-image:url(\'{art}\')" aria-hidden="true"></div><div class="answer-shade" aria-hidden="true"></div>' if art else ''
 add(ch,bg+'<div class="question"><span class="tag">考えてみてください</span><h2>'+q+'</h2><div class="cover-wrap"><div class="answer">'+a+'</div><button class="cover" type="button">クリックで開く</button></div></div>','think')
add(0,'''<div class="city"></div><svg class="currents" viewBox="0 0 1440 810" aria-hidden="true"><path d="M550 820C700 650 820 660 920 515S1100 420 1480 390"/><path d="M520 840C760 670 780 590 950 590S1120 650 1480 535"/><path d="M680 850C820 710 990 755 1100 540S1280 330 1500 270"/></svg><div class="title-copy"><div class="eyebrow">ニュースと経済がわかるシリーズ ｜ 第5回</div><h1>金利が動くと、<br>何が起きる？</h1><p class="subtitle">債券と株式の関係を、歴史でたどる</p><div class="rule"></div><p class="catch">金利が変わる。<br><em>お金の行き先が変わる。</em></p></div><div class="title-foot"><span>第1〜4回のダイジェストとともに</span><span>ALPHA Base ｜ 西村 真</span></div>''','title')
add(0,head('RECAP｜4回分を、ひとつの地図に','ここまでの4つの視点。')+cards([('01 マクロ経済','外の環境を読む','景気・物価・為替。<br>会社を取り巻く天気を見る。'),('02 株式の基礎','会社の持分を持つ','事業の挑戦を支え、<br>成果とリスクを分け合う。'),('03 株価のしくみ','期待が値段になる','利益と将来への見方が、<br>売り買いを通じて価格になる。'),('04 バブルと暴落','期待は、揺らぐ','値上がりの先に、<br>買い手がいるとは限らない。')]),'recap')
add(0,head('第5回でつながること','その期待を支える、<br>お金の条件。','借りるときの負担。貸すときの見返り。<br>その両方に関わるのが、金利。')+'<div class="route"><span>経済</span><i>→</i><span>企業</span><i>→</i><span>期待</span><i>→</i><span>値段</span></div><div class="underbar">金利は、この流れ全体に関わっている。</div>')
add(1,head('01｜お金のレンタル料','金利とは、<br>お金を使うための値段。','借りる側には「負担」。<br>貸す側には「見返り」。'),'chapter')
add(1,head('01-1｜同じ100万円でも','金利が変わると、負担が変わる。')+'''<div class="rate-demo"><div class="rate-control"><small>100万円を1年間借りる</small><strong id="rate">1<span>%</span></strong><div class="choices"><button data-rate="1" aria-pressed="true">年1%</button><button data-rate="3" aria-pressed="false">年3%</button><button data-rate="5" aria-pressed="false">年5%</button></div></div><div class="interest"><small>1年間の利息</small><strong id="cost">1万円</strong><div class="bar"><i id="costbar"></i></div><p>借りる金額が同じでも、<br>金利が上がると利息は増える。</p></div></div><p class="fine">元金を1年間据え置き、手数料を含めずに比較。</p>''')
question(1,'金利が上がると、<br>お金の使い方は変わる？','借りる負担が増える一方、<br>貯める・貸すことの魅力も変わる。','assets/rate05/interest-city-v1.png')
add(1,'<div class="city"></div><div class="hero-copy">金利が変わる。<br><em>お金の行き先が変わる。</em></div>','scene')
add(2,head('02｜もう一つの資産、債券','会社の持分を買う。<br>お金を貸す。','株式と債券は、企業や国を支える方法が違う。')+cards([('株式','共同オーナーになる','利益の分配や、<br>事業の成長を期待する。'),('債券','貸す側にまわる','利息と、期日に元本を<br>返してもらう約束を持つ。')]))
add(2,head('02-1｜債券のきほん','お金を貸して、約束を受け取る。')+'''<div class="bond-route"><div><small>買うとき</small><h3>投資家 → 発行体</h3><p>お金を渡す</p></div><b>→</b><div><small>保有する間</small><h3>利息を受け取る</h3><p>利払いの条件に従う</p></div><b>→</b><div><small>満期</small><h3>元本が返る</h3><p>発行体の返済能力が大切</p></div></div><p class="underbar">満期までの約束と、途中で売れる値段は別の話。</p>''')
question(3,'新しい債券の金利が上がったら、<br>前に買った債券は？','受け取る利息が変わらない固定利付債は、<br>相対的な魅力が下がり、価格が下がりやすい。')
add(3,head('03｜金利と債券価格','同じ約束でも、比較相手が変わる。')+'''<div class="bond-demo"><div class="bond-ticket"><small>保有している固定利付債</small><h3>毎年の利息は一定</h3><strong>変わらない約束</strong><p>市場金利が変わっても、<br>契約した利息はそのまま。</p></div><div class="bond-market"><div class="choices"><button id="yield-toggle" aria-pressed="false">市場金利を上げる</button></div><div class="arrows"><span>市場金利 <b id="yield-arrow">→</b></span><span>既発債の価格 <b id="price-arrow">→</b></span></div><p id="bond-note">新しい債券と、利息の条件を比べる。</p></div></div><p class="fine">信用力や残存期間など、ほかの条件が同じ場合。</p>''')
add(4,head('04｜金利と株価','株価に届く、3つの道すじ。')+cards([('企業の利益','借りる負担','借入コストが変わり、<br>利益や投資計画に影響する。'),('資産の比較','ほかの選択肢','債券などの利回りと、<br>株式の魅力を比べ直す。'),('将来の評価','未来の利益','将来受け取る利益を、<br>今どれだけ高く評価するか。')])+'<p class="underbar">「利上げなら必ず株安」とは限らない。理由と期待も見る。</p>')
add(4,head('04-1｜歴史でたどる','同じ金利の変化でも、背景は違う。')+cards([('物価が上がるとき','物価を抑えたい','金融引締めと、<br>企業の利益への影響を追う。'),('景気が弱るとき','景気を支えたい','金融緩和と、<br>先行きへの不安を分けて見る。'),('期待が先に動くとき','発表前から織り込む','金利の水準だけでなく、<br>予想との違いを確かめる。')]))
add(4,head('04-2｜物価が上がるとき','2022年、利上げは1年半続いた。')+'''<div class="chart"><div class="legend"><span class="gold">政策金利（米・実効FF金利）</span><span class="teal">株価（S&amp;P500・月末）</span></div>'''+series_chart('系列_2022利上げ.json')+'''</div><div class="chart-notes"><div><small>物価</small><p>前年比7〜9%まで上昇。<br>抑えるための利上げだった。</p></div><div><small>株価</small><p>利上げの前から下がり始め、<br>利上げが続く途中で戻り始めた。</p></div><div><small>見方</small><p>金利の水準だけでなく、<br>「いつ止まるか」の予想が値段に入る。</p></div></div><p class="fine">出典：FRED（FEDFUNDS, SP500, CPIAUCSL）。月次、2021〜2023年。株価の動きには企業利益や期待の変化も関わる。</p>''','history')
add(5,head('05｜ニュースで見ておきたい','まずは、3つの数字をつなぐ。')+cards([('01','政策金利','中央銀行は、<br>どう動こうとしているか。'),('02','長期金利','市場は、先の景気や物価を<br>どう見ているか。'),('03','物価上昇率','お金の購買力は、<br>どう変わっているか。')]))
add(5,head('総まとめ｜第1回から第5回へ','ニュースを、一本のつながりで読む。')+'''<div class="final-map"><span>経済の変化</span><i>→</i><span>企業の利益</span><i>→</i><span>将来への期待</span><i>→</i><span>売り買いと価格</span></div><div class="final-anchor">金利という、もう一つの軸。</div><p class="lead">何が変わったのか。誰に影響するのか。<br>その期待は、すでに値段に入っているのか。</p>''')
add(5,head('明日、ニュースを開いたら','数字の向こうの、<br>お金の動きを見よう。','5回分の視点が、ここでひとつにつながる。'),'ending')
