script='''const slides=[...document.querySelectorAll('.slide')],nav=[...document.querySelectorAll('nav button')];let current=0;function show(n){if(n<0||n>=slides.length)return;current=n;slides.forEach((s,i)=>{s.classList.toggle('on',i===n);s.inert=i!==n});nav.forEach(b=>b.classList.toggle('active',b.dataset.ch===slides[n].dataset.ch));document.querySelector('#count').textContent=(n+1)+' / '+slides.length}let lockedUntil=0;function step(d){if(performance.now()<lockedUntil)return;const s=slides[current];if(s.querySelector('.cover')){if(d>0&&!s.classList.contains('revealed')){s.classList.add('revealed');lockedUntil=performance.now()+850;return}if(d<0&&s.classList.contains('revealed')){s.classList.remove('revealed');return}}show(current+d)}document.querySelector('#next').onclick=()=>step(1);document.querySelector('#prev').onclick=()=>step(-1);nav.forEach(b=>b.onclick=()=>show(slides.findIndex(s=>s.dataset.ch===b.dataset.ch)));document.querySelectorAll('.cover').forEach(c=>c.onclick=e=>{e.stopPropagation();c.blur();step(1)});addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select')||e.repeat)return;const btn=e.target.closest('button');if(btn&&!btn.classList.contains('cover')&&[' ','Enter'].includes(e.key))return;if(['ArrowRight','PageDown',' ','Enter'].includes(e.key)){e.preventDefault();step(1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();step(-1)}if(e.key==='Home')show(0)});document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-rate]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.querySelector('#rate').innerHTML=b.dataset.rate+'<span>%</span>';document.querySelector('#cost').textContent=b.dataset.rate+'万円';document.querySelector('#costbar').style.width=Number(b.dataset.rate)*20+'%'});document.querySelector('#yield-toggle').onclick=function(){let on=this.getAttribute('aria-pressed')!=='true';this.setAttribute('aria-pressed',on);this.textContent=on?'元に戻す':'市場金利を上げる';document.querySelector('#yield-arrow').textContent=on?'↑':'→';document.querySelector('#price-arrow').textContent=on?'↓':'→';document.querySelector('#bond-note').textContent=on?'新しい債券の条件が良くなり、既発債は価格で調整される。':'新しい債券と、利息の条件を比べる。'};document.querySelector('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>{})};function fit(){document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1440,innerHeight/810))}addEventListener('resize',fit);fit();show(0);'''
html='<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>第5回｜金利が動くと何が起きる？</title><style>'+css+'</style></head><body><main id="stage"><nav aria-label="章へ移動"><b>第5回</b>'+''.join(f'<button data-ch="{i}">{t}</button>' for i,t in enumerate(['はじめに','1 金利','2 債券','3 価格','4 株価と歴史','5 総まとめ']))+'</nav>'+''.join(slides)+'<button class="fullscreen" id="fullscreen">全画面 ⛶</button><div class="pager"><button id="prev" aria-label="前へ">‹</button><span id="count"></span><button id="next" aria-label="次へ">›</button></div></main><script>'+script+'</script></body></html>'
(b/'sessions/05/index.html').write_text(html,encoding='utf-8')
